import functools
def ed(a, b):
    @functools.lru_cache(None)
    def f(i, j):
        if i == 0 or j == 0: return i + j
        return min(f(i - 1, j - 1) + (a[i - 1] != b[j - 1]), f(i - 1, j) + 1, f(i, j - 1) + 1)
    return f(len(a), len(b))
def bfs(s, t, letters):
    L = max(len(s), len(t)); seen = {s: 0}; todo = [s]
    for x in todo:
        if x == t: return seen[x]
        nxt = [x[:i] + x[i + 1:] for i in range(len(x))] + [x[:i] + c + x[i + 1:] for i in range(len(x)) for c in letters]
        if len(x) < L: nxt += [x[:i] + c + x[i:] for i in range(len(x) + 1) for c in letters]
        for y in nxt:
            if y not in seen: seen[y] = seen[x] + 1; todo.append(y)
result = bfs("LOVE", "MOVIE", "LOVEMI")

